"""Reference values for nomos's spatial interaction, from statsmodels 0.15 (BSD 3-Clause) and numpy.

    python -m venv env && env/bin/pip install statsmodels
    env/bin/python make_interaction_fixtures.py

Writes interaction_fixtures.hpp beside this file. Eight origins and nine destinations placed by a seeded generator on a
square of 20 km, the costs their distances plus 0.5 km; flows drawn as Poisson counts about a doubly constrained table at
β = 0.35 per km. statsmodels' GLM with the Poisson family, an intercept, origin and destination indicators and the cost as
regressors (Flowerdew and Aitkin 1982) gives the cost's coefficient, its model-based standard error and the fitted table:
Hyman's calibration of the doubly constrained model to the same table must give β = −coefficient and the same fitted table.
"""

from __future__ import annotations

from pathlib import Path

import numpy as np
import statsmodels
import statsmodels.api as sm

OUT = Path(__file__).with_name("interaction_fixtures.hpp")


def lit(a) -> str:
    return "{" + ", ".join(f"{float(x):.17g}" for x in np.ravel(a)) + "}"


def furness(seed, o, d, iterations=20000):
    b = np.ones(seed.shape[1])
    for _ in range(iterations):
        a = o / (seed @ b)
        b = d / (seed.T @ a)
    return (a[:, None] * seed) * b[None, :]


def main():
    rng = np.random.default_rng(20261111)
    R, C = 8, 9
    po = rng.uniform(0, 20, size=(R, 2))
    pd = rng.uniform(0, 20, size=(C, 2))
    cost = np.sqrt(((po[:, None, :] - pd[None, :, :]) ** 2).sum(axis=2)) + 0.5
    o = rng.uniform(200, 2000, size=R)
    d = rng.uniform(100, 1000, size=C)
    d *= o.sum() / d.sum()
    expected = furness(np.exp(-0.35 * cost), o, d)
    observed = rng.poisson(expected).astype(float)

    rows = np.repeat(np.arange(R), C)
    cols = np.tile(np.arange(C), R)
    X = np.column_stack([np.ones(R * C)] + [(rows == r).astype(float) for r in range(1, R)] + [(cols == c).astype(float) for c in range(1, C)] + [cost.ravel()])
    fit = sm.GLM(observed.ravel(), X, family=sm.families.Poisson()).fit(tol=1e-14, maxiter=200)
    coef = fit.params[-1]
    se = fit.bse[-1]
    fitted = fit.fittedvalues.reshape(R, C)

    text = f"""// Generated by make_interaction_fixtures.py with statsmodels {statsmodels.__version__} and numpy {np.__version__} (2026-11-11). Do not edit.
#pragma once
namespace interaction_fixtures {{
constexpr int rows = {R}, cols = {C};
constexpr double cost[] = {lit(cost)};
constexpr double observed[] = {lit(observed)};
constexpr double coefficient = {coef:.17g};   // the cost's, so that beta = -coefficient
constexpr double standard_error = {se:.17g};
constexpr double fitted[] = {lit(fitted)};
}}  // namespace interaction_fixtures
"""
    OUT.write_text(text, encoding="utf-8", newline="\n")
    print(f"beta = {-coef:.12g} (se {se:.3g}); deviance {fit.deviance:.6g}; wrote {OUT.name}")


if __name__ == "__main__":
    main()
